from collections import deque
import heapq
def bfs(g, r, c, sources, dirs, passable):
    INF = -1
    dist = [[INF] * c for _ in range(r)]
    q = deque()
    for (i, j) in sources:
        dist[i][j] = 0
        q.append((i, j))
    while q:
        i, j = q.popleft()
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < r and 0 <= nj < c and dist[ni][nj] == INF and passable(g[ni][nj]):
                dist[ni][nj] = dist[i][j] + 1
                q.append((ni, nj))
    return dist

def cells(g, r, c, ch):
    return [(i, j) for i in range(r) for j in range(c) if g[i][j] == ch]

def s_ob1q1(r, c, g):
