import sys
from collections import deque
import heapq
def bfs(g, r, c, sources, dirs, passable):
    INF = -1
    dist = [[INF] * c for _ in range(r)]
    q = deque()
    for (i, j) in sources:
        dist[i][j] = 0
        q.append((i, j))
    while q:
        i, j = q.popleft()
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < r and 0 <= nj < c and dist[ni][nj] == INF and passable(g[ni][nj]):
                dist[ni][nj] = dist[i][j] + 1
                q.append((ni, nj))
    return dist

def cells(g, r, c, ch):
    return [(i, j) for i in range(r) for j in range(c) if g[i][j] == ch]

def _pockets(r, c, unserved):
    seen = [[False] * c for _ in range(r)]
    groups = 0; largest = 0
    for i in range(r):
        for j in range(c):
            if unserved[i][j] and not seen[i][j]:
                groups += 1; size = 0
                q = deque([(i, j)]); seen[i][j] = True
                while q:
                    a, b = q.popleft(); size += 1
                    for di, dj in D4:
                        x, y = a + di, b + dj
                        if 0 <= x < r and 0 <= y < c and unserved[x][y] and not seen[x][y]:
                            seen[x][y] = True; q.append((x, y))
                largest = max(largest, size)
    return f"{groups} {largest}"

def s_ob1q3(r, c, k, g):
    dist = bfs(g, r, c, cells(g, r, c, 'H'), D8, lambda ch: ch != '#')
    uns = [[g[i][j] == '.' and (dist[i][j] == -1 or dist[i][j] > k) for j in range(c)] for i in range(r)]
    return _pockets(r, c, uns)

D4 = ((1, 0), (-1, 0), (0, 1), (0, -1))
D8 = D4 + ((1, 1), (1, -1), (-1, 1), (-1, -1))
data = sys.stdin.read().split()
if data:
    r, c, k = int(data[0]), int(data[1]), int(data[2]); g = data[3:3 + r]
    print(s_ob1q3(r, c, k, g))

